//! `std::cout << some_float` reproduced byte for byte.
//!
//! libstdc++ implements `num_put<char>::do_put(float)` by handing the value to
//! `printf` with a `%g`-family conversion, so a default-configured `std::ostream`
//! prints a `float` exactly like `printf("%g", (double)f)`: six significant
//! digits, trailing zeros stripped, and the `%e`/`%f` style chosen from the
//! decimal exponent.
//!
//! The subtle part is rounding. `printf` rounds the *exact* binary value, with
//! ties going to even. `f32::to_string` instead prints the shortest string that
//! round-trips, so `57.0/128.0` comes out as `0.4453125` in Rust and `0.445312`
//! in C++. To get the C++ answer we expand the float exactly (see
//! [`crate::cxx::bigdec`]) and round that expansion ourselves.

use super::bigdec::{decompose_f32, ExactDecimal, FloatClass};

/// Default `std::ios_base` precision, and therefore `%g`'s significant digits.
pub const DEFAULT_PRECISION: usize = 6;

/// Format a `float` the way a default-constructed `std::ostream` would.
pub fn to_string_f32(value: f32) -> String {
    format_g(value, DEFAULT_PRECISION)
}

/// `printf("%.*g", precision, (double)value)` for a value that came from a `f32`.
pub fn format_g(value: f32, precision: usize) -> String {
    // C99 7.19.6.1: for %g, "if the precision is zero, it is taken as 1".
    let p = precision.max(1);

    let parts = decompose_f32(value);
    let sign = if parts.negative { "-" } else { "" };

    match parts.class {
        // glibc prints the sign of a negative NaN, matching what libstdc++ emits.
        FloatClass::Nan => return format!("{sign}nan"),
        FloatClass::Infinite => return format!("{sign}inf"),
        // Zero takes the %f branch (X == 0) and then loses its fraction to
        // trailing-zero stripping, leaving a bare "0".
        FloatClass::Zero => return format!("{sign}0"),
        FloatClass::Finite => {}
    }

    let exact = parts.decimal.expect("finite values carry an expansion");
    let (mut significand, exp10) = round_to_significant_digits(&exact, p);

    // X is the exponent %g would print in style e *after* rounding, which is why
    // rounding has to happen before the style is chosen: rounding 9.999995e-5 up
    // moves X from -5 to -4 and switches styles.
    let x = exp10 - 1;

    // Pad so the caller can index a full p digits regardless of how many the
    // expansion actually had.
    significand.resize(p, 0);

    // C99 7.19.6.1: style e is used unless -4 <= X < P.
    let body = if x < -4 || x >= p as i32 {
        render_style_e(&significand, x)
    } else {
        render_style_f(&significand, x)
    };

    format!("{sign}{body}")
}

/// Round an exact expansion to `p` significant digits the way `printf` does:
/// look at everything that is being discarded, and break exact ties towards the
/// even digit.
///
/// Returns the kept digits (at most `p`, possibly fewer if the expansion was
/// shorter) and the possibly incremented decimal exponent.
fn round_to_significant_digits(exact: &ExactDecimal, p: usize) -> (Vec<u8>, i32) {
    let digits = &exact.digits;
    if digits.len() <= p {
        return (digits.clone(), exact.exp10);
    }

    let mut kept = digits[..p].to_vec();
    let first_dropped = digits[p];
    let rest_nonzero = digits[p + 1..].iter().any(|&d| d != 0);

    let round_up = match first_dropped.cmp(&5) {
        std::cmp::Ordering::Greater => true,
        std::cmp::Ordering::Less => false,
        // Exactly halfway: the expansion is exact, so this really is a tie.
        std::cmp::Ordering::Equal => rest_nonzero || kept[p - 1] % 2 == 1,
    };

    if !round_up {
        return (kept, exact.exp10);
    }

    let mut exp10 = exact.exp10;
    let mut i = p;
    loop {
        if i == 0 {
            // 999999 -> 1000000: one more digit, so the exponent grows and the
            // significand becomes 1 followed by zeros.
            kept.insert(0, 1);
            kept.truncate(p);
            exp10 += 1;
            break;
        }
        i -= 1;
        if kept[i] == 9 {
            kept[i] = 0;
        } else {
            kept[i] += 1;
            break;
        }
    }

    (kept, exp10)
}

/// `%e` with precision `p - 1`, then trailing zeros stripped.
fn render_style_e(significand: &[u8], x: i32) -> String {
    let mut out = String::with_capacity(significand.len() + 8);
    out.push(digit_char(significand[0]));

    let fraction = strip_trailing_zeros(&significand[1..]);
    if !fraction.is_empty() {
        out.push('.');
        out.extend(fraction.iter().map(|&d| digit_char(d)));
    }

    out.push('e');
    out.push(if x < 0 { '-' } else { '+' });
    let magnitude = x.unsigned_abs();
    // The exponent field is at least two digits wide.
    if magnitude < 10 {
        out.push('0');
    }
    out.push_str(&magnitude.to_string());
    out
}

/// `%f` with precision `p - 1 - X`, then trailing zeros stripped. The decimal
/// point goes away with them when nothing is left after it.
fn render_style_f(significand: &[u8], x: i32) -> String {
    let mut integer = String::new();
    let mut fraction: Vec<u8> = Vec::new();

    if x >= 0 {
        let split = x as usize + 1; // x < p, so this stays in range
        integer.extend(significand[..split].iter().map(|&d| digit_char(d)));
        fraction.extend_from_slice(&significand[split..]);
    } else {
        integer.push('0');
        // -4 <= x <= -1 here, so at most three leading zeros are inserted.
        fraction.resize((-x - 1) as usize, 0);
        fraction.extend_from_slice(significand);
    }

    let fraction = strip_trailing_zeros(&fraction);
    if fraction.is_empty() {
        integer
    } else {
        let mut out = integer;
        out.push('.');
        out.extend(fraction.iter().map(|&d| digit_char(d)));
        out
    }
}

fn strip_trailing_zeros(digits: &[u8]) -> &[u8] {
    let end = digits
        .iter()
        .rposition(|&d| d != 0)
        .map_or(0, |last| last + 1);
    &digits[..end]
}

fn digit_char(d: u8) -> char {
    (b'0' + d) as char
}

