        assert_eq!(to_string_f32(1234.5), "1234.5");
        assert_eq!(to_string_f32(999999.0), "999999");
        assert_eq!(to_string_f32(1.0e6), "1e+06");
        assert_eq!(to_string_f32(1.0e-4), "0.0001");
        assert_eq!(to_string_f32(1.0e-5), "1e-05");
        assert_eq!(to_string_f32(1.5e-7), "1.5e-07");
        assert_eq!(to_string_f32(1.0e38), "1e+38");
    }

    #[test]
    fn rounding_can_move_the_style_boundary() {
        // 999999.5 rounds to 1000000, which has X == 6 and so prints in style e.
        assert_eq!(to_string_f32(999999.5), "1e+06");
        // 9.9999995e-5 rounds up to 0.0001, moving X from -5 to -4 (style f).
        assert_eq!(to_string_f32(9.99999e-5), "9.99999e-05");
    }

