/*
 * Corpus generator for the %g differential test.
 *
 * Emits one "<float bits in hex>\t<printf %g output>" line per value so that the
 * Rust implementation in cxx/ostream.rs can be checked against the very libc that
 * printed the reference binary's output.
 *
 * An optional argument overrides the precision, so the formatter can be checked
 * away from the default of 6 as well.
 *
 *   gcc -O2 -o gen_corpus gen_corpus.c && ./gen_corpus [precision] > gcorpus.tsv
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <float.h>

static int precision = 6;

static void emit(float f) {
    uint32_t bits;
    memcpy(&bits, &f, sizeof bits);
    printf("%08x\t%.*g\n", bits, precision, (double)f);
}

int main(int argc, char **argv) {
    if (argc > 1) precision = atoi(argv[1]);
    /* 1. Every value a load factor can be: n / 2^k. These are exact binary
     *    fractions, so their decimal expansions terminate and land on printf's
     *    ties-to-even path far more often than random values do. */
    for (int k = 1; k <= 24; k++) {
        long denom = 1L << k;
        long limit = denom < 4096 ? denom : 4096;
        for (long n = 0; n <= limit; n++) {
            emit((float)n / (float)denom);
        }
    }

    /* 2. Values whose 7th significant digit is a 5 with nothing after it: exact
     *    decimal ties, where the kept digit's parity decides the answer. */
    for (long n = 1; n < 20000; n++) {
        emit((float)n / 128.0f);
        emit((float)n / 256.0f);
        emit((float)n / 512.0f);
        emit((float)n / 1024.0f);
        emit((float)n / 2048.0f);
    }

    /* 3. The %g style boundaries: style e is used unless -4 <= X < 6, and
     *    rounding happens first, so a value can cross the boundary by rounding. */
    static const float edges[] = {
        0.0f, -0.0f, 1.0f, -1.0f, 9.999994f, 9.999996f, 10.0f,
        1e-5f, 9.99999e-5f, 9.999995e-5f, 1e-4f, 1.000001e-4f,
        999998.5f, 999999.0f, 999999.4f, 999999.5f, 999999.6f, 1e6f, 1000001.0f,
        1234567.0f, 12345678.0f, 0.1f, 0.5f, 1.0f / 3.0f, 2.0f / 3.0f,
